export default class Bootstrapper {
  static SearchBuilder = SearchBuilder;

  // expose constants
  static CODEC_XOR = CODEC_XOR;
  static CODEC_PLAIN = CODEC_PLAIN;
  static LOG_TRACE = LOG_TRACE;
  static LOG_DEBUG = LOG_DEBUG;
  static LOG_INFO = LOG_INFO;
  static LOG_WARN = LOG_WARN;
  static LOG_ERROR = LOG_ERROR;
  static LOG_SILENT = LOG_SILENT;

  constructor(config) {
    if (typeof config.directory !== 'string') {
      throw new TypeError(`Directory must be a string`);
    }

    this.config = config;
    this.ready = this.register();
  }

  async register() {
    try {
      // Check if the browser supports service workers
      if (!('serviceWorker' in navigator)) {
        throw new Error('Your browser does not support service workers.');
      }

      const workerUrl = `${this.config.directory}worker.js?config=${encodeURIComponent(
        JSON.stringify(this.config)
      )}`;

      // Register the service worker
      this.worker = await navigator.serviceWorker.register(workerUrl, {
        scope: this.config.directory,
        updateViaCache: 'none',
      });

      // Wait for the service worker to update
      await this.worker.update();

      // Log if the log level is set to debug
      if (this.config.loglevel <= LOG_DEBUG) {
        console.debug('Service worker registered successfully.');
      }
    } catch (error) {
      // Handle errors (network issues, registration issues, etc.)
      console.error('Failed to register service worker:', error);
      alert('Error: Service worker registration failed!')
